    let mut store: DocumentStore<User> = DocumentStore::new(2);  // tiny cache on purpose — forces a real eviction below

    store.put("user:001".into(), User { name: "Ada".into(), age: 34, active: true });
    store.put("user:002".into(), User { name: "Grace".into(), age: 45, active: false });
    store.put("user:003".into(), User { name: "Linus".into(), age: 29, active: true });

    assert_eq!(store.get("user:001")?.name, "Ada");
    assert_eq!(store.get("user:002")?.name, "Grace");
    assert_eq!(store.get("user:003")?.name, "Linus");  // cache capacity 2 -> this evicts "user:001" from the CACHE only, not the backing store
    assert_eq!(store.get("user:001")?.name, "Ada");  // still correct — falls through to the BTreeMap on cache miss, exactly as designed

    match store.get("user:999") {
        Err(StoreError::NotFound(key)) => assert_eq!(key, "user:999"),
        _ => panic!("expected NotFound"),
    }

    let active_over_30 = store.query(|u| u.active && u.age > 30);  // closure as a first-class predicate — no query-language string parsing anywhere
    assert_eq!(active_over_30.len(), 1);
    assert_eq!(active_over_30[0].1.name, "Ada");

