    assert_eq!(range.len(), 2);  // "user:001" and "user:002" — end bound exclusive

    let total_age: u32 = store.query(|_| true).iter().fold(0, |acc, (_, u)| acc + u.age);  // fold — combining iterators + closures + generics in one line
    assert_eq!(total_age, 34 + 45 + 29);

    let deleted = store.delete("user:002");
    assert_eq!(deleted.map(|u| u.name), Some("Grace".to_string()));
    assert!(store.get("user:002").is_err());

    Ok(())
}

